// v0.7 "Elements & Counters": hand-designed signature cards for the seven new classes, Counter cards for
// every faction, and the new enemy traps. The systematic card pool lives in cardgen.ts.
//
// Counter cards sit in your hand (they Retain) and are played from it in the middle of a chain: when an
// enemy trap or Reaction fires (or, for "an attack" Counters, when an enemy attacks), you may answer it.
// On your turn you pay with energy; on the enemy turn you pay with Flux (energy you carried over).
// Their effect is `react`, with the answered link as the trigger (so `c.negate()` cancels it and
// `c.tgt` is the enemy that made it). A Counter can itself be answered: by enemy traps that fire on
// Reactions, and by elite and boss Rebuttals. You can counter those too, up to 2 links past the cap.
import type { CardDef } from '../engine/types';

const negIfFrozen = (c: import('../engine/combat').Ctx): void => {
  if (c.tgt?.st.frozen) { delete c.tgt.st.frozen; c.negate(); }
};

